export type MessageKey = keyof typeof rows

function build() {
  const table = {} as Record<LocaleId, Record<MessageKey, string>>
  for (const id of localeIds) table[id] = {} as Record<MessageKey, string>
  for (const key of Object.keys(rows) as MessageKey[]) {
    const values = rows[key]
    localeIds.forEach((id, index) => {
      table[id][key] = values[index]
    })
  }
  return table
}

export const messages = build()
